16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.util.*;
25	
26	/**
27	 * Simple JavaBean domain object representing an owner.
28	 *
29	 * @author Ken Krebs
30	 * @author Juergen Hoeller
31	 * @author Sam Brannen
32	 * @author Michael Isvy
33	 */
34	@Entity
35	@Table(name = "owners")
36	@EntityListeners(OwnerAuditListener.class)
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    private String address;
40	
41	    @Transient
42	    private String addressLine1;
43	
44	    @Transient
45	    private String addressLine2;
46	
47	    @Column(name = "city")
48	    @NotEmpty
49	    private String city;
50	
51	    @Column(name = "telephone")
52	    @NotEmpty
53	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be a valid E.164 number")
54	    private String telephone;
55	
56	    @Column(name = "email")
57	    private String email;
58	
59	    @Column(name = "postcode")
60	    private String postcode;
61	
62	    @Column(name = "title")
63	    private String title;
64	
65	    @Column(name = "customer_code")
66	    private String customerCode;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "household_member_count")
72	    private Integer householdMemberCount;
73	
74	    @Column(name = "namesake_count")
75	    private Integer namesakeCount;
76	
77	    @Column(name = "registration_date")
78	    private java.time.LocalDate registrationDate;
79	
80	    @Column(name = "birth_date")
81	    private java.time.LocalDate birthDate;
82	
83	    @Column(name = "bulk_signup_warning")
84	    private Boolean bulkSignupWarning;
85	
86	    @Column(name = "possible_duplicate_of")
87	    private Integer possibleDuplicateOf;
88	
89	    @Column(name = "deleted")
90	    private Boolean deleted;
91	
92	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
93	    private Set<Pet> pets;
94	
95	    @PrePersist
96	    private void defaultRegistrationDate() {
97	        if (this.registrationDate == null) {
98	            this.registrationDate = java.time.LocalDate.now();
99	        }
100	    }
101	
102	    public java.time.LocalDate getRegistrationDate() {
103	        return this.registrationDate;
104	    }
105	
106	    /** True when more than 80 owners were already created on this owner's registration date. */
107	    public Boolean getBulkSignupWarning() {
108	        return this.bulkSignupWarning != null && this.bulkSignupWarning;
109	    }
110	
111	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
112	        this.bulkSignupWarning = bulkSignupWarning;
113	    }
114	
115	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
116	        this.registrationDate = registrationDate;
117	    }
118	
119	    public java.time.LocalDate getBirthDate() {
120	        return this.birthDate;
121	    }
122	
123	    public void setBirthDate(java.time.LocalDate birthDate) {
124	        this.birthDate = birthDate;
125	    }
126	
127	    public String getTitle() {
128	        return this.title;
129	    }
130	
131	    public void setTitle(String title) {
132	        this.title = title;
133	    }
134	
135	    /** Salutation composed from the optional title and last name (see {@link Salutations}). */
136	    public String getSalutation() {
137	        return Salutations.compose(this.title, this.lastName);
138	    }
139	
140	    public String getCustomerCode() {
141	        return this.customerCode;
142	    }
143	
