package org.springframework.samples.petclinic.model;

import java.util.Locale;
import java.util.Map;

/**
 * Normalises a raw postal address: trims and collapses whitespace, upper-cases,
 * and expands common abbreviations ({@code ST->STREET}, {@code RD->ROAD},
 * {@code AVE->AVENUE}).
 */
final class PostalAddress {

    private static final Map<String, String> ABBREVIATIONS = Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    private PostalAddress() {
    }

    /**
     * The effective address: the composed structured lines when {@code line1} is
     * present (a single space joining a present {@code line2}), otherwise {@code flat}.
     * Both lines are expected to be already {@link #normalize(String) normalized}.
     */
    static String compose(String line1, String line2, String flat) {
        if (line1 == null || line1.isBlank()) {
            return flat;
        }
        return (line2 == null || line2.isBlank()) ? line1 : line1 + " " + line2;
    }

    /** Returns {@code null} for a {@code null} input. */
    static String normalize(String raw) {
        if (raw == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        for (String word : raw.strip().split("\\s+")) {
            String upper = word.toUpperCase(Locale.ROOT);
            if (!sb.isEmpty()) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(upper, upper));
        }
        return sb.toString();
    }
}

